const getTrialBalance = `-- name: GetTrialBalance :many
SELECT
  a.id,
  a.account_code,
  a.account_name,
  a.root_type,
  a.account_type,
  a.normal_balance,
  COALESCE(
    SUM(
      CASE
        WHEN te.debit_amount > 0 THEN te.debit_amount
        ELSE 0
      END
    ),
    0
  ) AS total_debits,
  COALESCE(
    SUM(
      CASE
        WHEN te.credit_amount > 0 THEN te.credit_amount
        ELSE 0
      END
    ),
    0
  ) AS total_credits,
  COALESCE(
    SUM(
      CASE
        WHEN te.debit_amount > 0 THEN te.debit_amount
        ELSE - te.credit_amount
      END
    ),
    0
  ) AS net_balance
FROM
  finance_accounts a
  LEFT JOIN finance_transaction_entries te ON a.id = te.account_id
  AND te.tenant_id = current_tenant_id()
  AND te.deleted_at IS NULL
  LEFT JOIN finance_transactions t ON te.transaction_id = t.id
  AND t.transaction_status = 'POSTED'
  AND (
    $1::date IS NULL
    OR t.posting_date <= $1::date
  )
WHERE
  a.tenant_id = current_tenant_id()
  AND a.deleted_at IS NULL
  AND a.is_active = TRUE
GROUP BY
  a.id,
  a.account_code,
  a.account_name,
  a.root_type,
  a.account_type,
  a.normal_balance
HAVING
  COALESCE(
    SUM(
      CASE
        WHEN te.debit_amount > 0 THEN te.debit_amount
        ELSE 0
      END
    ),
    0
  ) != 0
  OR COALESCE(
    SUM(
      CASE
        WHEN te.credit_amount > 0 THEN te.credit_amount
        ELSE 0
      END
    ),
    0
  ) != 0
  OR $2 = TRUE
ORDER BY
  a.account_code ASC
`

type GetTrialBalanceParams struct {
	AsOfDate            time.Time   `json:"as_of_date"`
	IncludeZeroBalances interface{} `json:"include_zero_balances"`
}

